agent-tree.css:
/* the card's design switch: Classic, Cost tree and Cost map, with the switch under the tree (on designme.dev it is the
   card's footer tabs). Each design sits centred in the room the card keeps for the tallest of them, and grows from there
   with its content, up and down alike (owner, 17 Nov) */
.dm.atr-dm{min-height:0;flex:1;gap:var(--dm-s-5)}
.atr-dm>.dm-main>*{width:100%}
.stage-in:has(>.atr-dm){align-self:auto;display:flex;flex-direction:column}
/* the two other designs take the Classic tree's treatment (owner, 16 Nov): its header, its 14px marks (a ring while queued,
   a spinner while running, a filled disc with a tick or a cross once done or failed, the accent disc where the run starts,
   the accent ring while a step waits for a person), its avatars and app logos, and, in Cost tree, its lines and band. Agent
   colours stay on the avatars; cost is the accent, in one step per agent (--dm-k1 to --dm-k3, each 3:1 or more on the surface).
   Lighter steps would drop under 3:1, so the steps run from the accent towards the text colour, and in Blueprint's dark
   theme, where the lime is already light, towards the surface */
.atr-ct,.atr-cm{--dm-k1:var(--dm-accent-mark,var(--dm-accent));--dm-k2:color-mix(in oklab,var(--dm-accent-mark,var(--dm-accent)) 74%,var(--dm-fg));--dm-k3:color-mix(in oklab,var(--dm-accent-mark,var(--dm-accent)) 50%,var(--dm-fg))}
:root:not([data-style="soft"],[data-style="clean"])[data-theme="dark"] :is(.atr-ct,.atr-cm):not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){--dm-k2:color-mix(in oklab,var(--dm-accent-mark,var(--dm-accent)) 70%,var(--dm-surface));--dm-k3:color-mix(in oklab,var(--dm-accent-mark,var(--dm-accent)) 46%,var(--dm-surface))}
@media (prefers-color-scheme:dark){:root:not([data-style="soft"],[data-style="clean"]):not([data-theme="light"]) :is(.atr-ct,.atr-cm):not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){--dm-k2:color-mix(in oklab,var(--dm-accent-mark,var(--dm-accent)) 70%,var(--dm-surface));--dm-k3:color-mix(in oklab,var(--dm-accent-mark,var(--dm-accent)) 46%,var(--dm-surface))}}
.atr-x-fix{flex:none}
/* Cost tree: the Classic tree with each row's share of the whole run as a bar after its cost, and the run's cost by agent
   as one bar under the header. A row's bar and its agent's part of the run's bar are the same step of the accent */
.atr-ct .atr-h{padding-bottom:var(--dm-s-2)}
/* the whole run's cost, one bar: each agent's part in its step of the accent, clipped to its stretch (--dm-x0 to --dm-x1, in
   percent) so it grows without a layout, with a 2px gap of the surface between parts; what is left at the end is the
   orchestrator's own, on the grey track */
.atr-ct-mix{position:relative;height:6px;margin:0 var(--dm-s-2) var(--dm-s-3);border-radius:calc(3px * var(--dm-rk-s,var(--dm-rk)));overflow:hidden;background:color-mix(in srgb,var(--dm-line) 50%,transparent)}
.atr-ct-mix i{position:absolute;inset:0;background:var(--dm-k);clip-path:inset(0 calc(100% - var(--dm-x1,0) * 1% + 1px) 0 calc(var(--dm-x0,0) * 1% + 1px) round calc(3px * var(--dm-rk-s,var(--dm-rk))));transition:clip-path .8s var(--dm-ease)}
/* each row's cost, then its branch's share of the whole as a short bar in its agent's step of the accent */
.atr-ct .atr-q{align-items:center;gap:var(--dm-s-2)}
.atr-ct .atr-c{min-width:38px;text-align:right}
.atr-ct-bar{display:block;width:40px;height:3px;flex:none;border-radius:calc(2px * var(--dm-rk-s,var(--dm-rk)));overflow:hidden;background:color-mix(in srgb,var(--dm-line) 50%,transparent)}
.atr-ct-bar span{display:block;height:100%;border-radius:inherit;background:var(--dm-k,var(--dm-k1));transform-origin:left;transform:scaleX(var(--dm-sh,0));transition:transform .5s var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.atr-b:hover .atr-ct-bar{background:var(--dm-surface)}}
.atr-n[data-dim]>.atr-b .atr-ct-bar span{opacity:.5}
/* the end: one line with the done mark, under the tree */
.atr-ct-sum{display:flex;align-items:center;gap:var(--dm-s-2);margin:var(--dm-s-1) 0 0;padding:var(--dm-s-2);font-size:12.5px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.atr-ct-sum b{font-weight:500;color:var(--dm-fg)}
.atr-ct-sum[data-in]{animation:atrin .56s var(--dm-atr-ez) backwards}
@container atr (max-width:360px){.atr-ct-bar{width:28px}.atr-ct .atr-c{min-width:34px}}
/* narrower still, the rows keep their cost and leave the bar to the run's bar above, so the names keep their room */
@container atr (max-width:340px){.atr-ct-bar{display:none}}
:root:not([data-style="soft"],[data-style="clean"]) .atr-ct-mix i:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){transition:clip-path .4s steps(4,end)}
:root:not([data-style="soft"],[data-style="clean"]) .atr-ct-bar span:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){transition:transform .3s steps(3,end)}
/* Cost map: every agent and step as a block as wide as its cost, one row for each level. A block's place and width are set
   with a transform and a clip, so as costs grow and as you zoom the blocks slide and stretch without a layout. Blocks are
   flat: the whole run and finished work grey, the accent tint while at work or waiting for a person, the bad tint when failed, the hover grey
   while queued, and each carries its state as the tree's mark, so the colour is never the only sign. An agent's own work,
   outside its steps, is a light grey hatch */
.atr-cm{display:flex;flex-direction:column;gap:10px;padding:var(--dm-s-2) var(--dm-s-3) var(--dm-s-3)}
.atr-cm .atr-h{padding:var(--dm-s-1) 0 0}
.atr-cm-crumb{display:flex;align-items:center;gap:4px;min-width:0;font-size:14px}
.atr-cm-crumb button{border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));padding:2px 4px;margin:-2px -4px;color:var(--dm-fg2);transition:background .2s,color .2s}
@media (hover:hover) and (pointer:fine){.atr-cm-crumb button:hover{background:var(--dm-row);color:var(--dm-fg)}}
.atr-cm-crumb b{font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.atr-cm-crumb .i{color:var(--dm-faint)}
.atr-cm-map{position:relative;height:calc(3 * 52px + 2 * 4px);overflow:hidden}
.atr-cm-b{position:absolute;left:0;top:calc(var(--dm-lv) * 56px);width:100%;height:52px;transform:translateX(var(--dm-x,0px));transition:transform .7s var(--dm-ease),clip-path .7s var(--dm-ease),opacity .4s;text-align:left;outline:0;clip-path:inset(0 calc(100% - var(--dm-w,0px)) 0 0 round calc(8px * var(--dm-rk-m,var(--dm-rk))))}
.atr-cm-b .bg{position:absolute;inset:0;background-color:var(--dm-chip);transition:background-color .3s}
.atr-cm-b:not(.lv0):is([data-s="run"],[data-s="wait"]) .bg{background-color:color-mix(in srgb,var(--dm-atr-run) 14%,var(--dm-surface))}
.atr-cm-b:not(.lv0)[data-s="fail"] .bg{background-color:var(--dm-bad-bg)}
.atr-cm-b:not(.lv0)[data-s="queued"] .bg{background-color:var(--dm-row)}
.atr-cm-b.own .bg{background-color:var(--dm-row);background-image:repeating-linear-gradient(135deg,transparent 0 4px,color-mix(in srgb,var(--dm-fg) 7%,transparent) 4px 5px)}
/* under the pointer a block takes a neutral step darker, keeping its tint */
.atr-cm-b:not(.own):focus-visible .bg{background-image:linear-gradient(color-mix(in srgb,var(--dm-fg) 5%,transparent),color-mix(in srgb,var(--dm-fg) 5%,transparent))}
@media (hover:hover) and (pointer:fine){.atr-cm-b:not(.own):hover .bg{background-image:linear-gradient(color-mix(in srgb,var(--dm-fg) 5%,transparent),color-mix(in srgb,var(--dm-fg) 5%,transparent))}}
.atr-cm-b:focus-visible .atr-cm-l b{text-decoration:underline;text-decoration-color:var(--dm-focus);text-underline-offset:3px;text-decoration-thickness:2px}
.atr-cm-l{position:absolute;left:8px;top:8px;width:calc(var(--dm-w,0px) - 16px);display:grid;grid-template-columns:auto minmax(0,1fr);column-gap:6px;align-items:center;font-size:12.5px;line-height:1.35;white-space:nowrap;pointer-events:none;color:var(--dm-fg);transition:opacity .3s}
.atr-cm-l .atr-g{grid-row:1}
.atr-cm-l b{font-weight:500;overflow:hidden;text-overflow:ellipsis}
.atr-cm-l .v{grid-column:2;font-size:12px;color:var(--dm-fg2);font-variant-numeric:tabular-nums}
.atr-cm-b.gone{opacity:0;pointer-events:none}
/* a block too narrow for its words keeps its mark; one too narrow for that keeps only its tint (its tooltip says the rest) */
.atr-cm-l[data-fit="mark"]>:not(.atr-g){opacity:0}
.atr-cm-l[data-fit="none"]{opacity:0}
/* the key to the blocks, under the map: the marks, and the hatch for an agent's own work */
.atr-cm-lg{list-style:none;margin:-2px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:4px 14px;font-size:12px;color:var(--dm-muted)}
.atr-cm-lg li{display:inline-flex;align-items:center;gap:6px}
.atr-cm-lg .atr-g{transform:scale(.86)}
.atr-cm-lg .own{width:12px;height:12px;flex:none;border-radius:calc(3px * var(--dm-rk-s,var(--dm-rk)));background:var(--dm-row) repeating-linear-gradient(135deg,transparent 0 2px,color-mix(in srgb,var(--dm-fg) 30%,transparent) 2px 3px)}
.atr-cm-say{min-height:20px;font-size:12.5px;color:var(--dm-fg2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.atr-cm-say b{font-weight:500;color:var(--dm-fg)}
/* each agent: its mark and avatar, as in the tree, its share and its cost, and the way on when it needs one */
.atr-cm-key{list-style:none;margin:0;padding:0;display:flex;flex-direction:column}
.atr-cm-key li{display:flex;align-items:center;gap:var(--dm-s-2);min-height:36px;padding:0 var(--dm-s-1);font-size:13px}
.atr-cm-key .t{flex:1;min-width:0;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.atr-cm-key .p{width:38px;text-align:right;font-size:12px;color:var(--dm-muted);font-variant-numeric:tabular-nums}
.atr-cm-key .c{width:44px;text-align:right;font-size:12px;color:var(--dm-fg2);font-variant-numeric:tabular-nums}
.atr-cm-key .pill{margin-left:2px}
/* on a phone the key leaves out each agent's share, which its blocks already show, so the names keep their room */
@container atr (max-width:360px){.atr-cm-key .p{display:none}}
:root:not([data-style="soft"],[data-style="clean"]) .atr-cm-b:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){clip-path:inset(0 calc(100% - var(--dm-w,0px) + 2px) 0 0);transition-duration:.45s;transition-timing-function:steps(5,end)}
:root:not([data-style="soft"],[data-style="clean"]) .atr-cm-b[data-s="fail"] .bg:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){background-image:repeating-linear-gradient(135deg,transparent 0 4px,color-mix(in srgb,var(--dm-bad) 14%,transparent) 4px 5px)}
:root:not([data-style="soft"],[data-style="clean"]) .atr-cm-lg .own:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){border-radius:0}

agent-tree.js:
/* ---------- Agent tree designs ---------- */
{
  const classic = DM.defs['agent-tree'];
  // the card has three designs, picked with the switch under the tree (on designme.dev, the card's footer tabs): Classic, the
  // tree; Cost tree, the same tree with each branch's share of the cost as a bar in the accent; and Cost map, every agent and
  // step as a block as wide as its cost. The two cost designs play Classic's run, with its agents, steps and marks: the
  // orchestrator splits the work between three agents, one design step fails on a token the library doesn't have and is
  // rerouted to a retry, and the copy agent's post waits for your OK. Every row is there from the start (the plan, in rings)
  // but the retry, which joins when the step fails. cost is what each spends itself, in dollars, and it grows while it
  // runs; a branch's cost is its own and everything under it
  const ATR_RUN = [
    { id:'root', n:'Orchestrator', t:'Splitting the work', ic:'spark', s:'run', cost:.004 },
    { id:'res', p:'root', n:'Research', t:'5 competitor pages', ic:'globe', av:'l', s:'run', cost:.003 },
    { id:'res1', p:'res', n:'Read the pages', t:'Reading 1 of 5', ic:'file-text', s:'run', cost:.006 },
    { id:'des', p:'root', n:'Design', t:'Plan cards in Figma', ic:'palette', av:'p', s:'run', cost:.003 },
    { id:'des1', p:'des', n:'Update cards', t:'Pricing v4', app:'figma', s:'run', cost:.005 },
    { id:'des2', p:'des', n:'Brand tokens', t:'Colours and spacing', app:'figma' },
    { id:'des3', p:'des', n:'Retry tokens', t:'Rerouted to accent.500', app:'figma', late:true },
    { id:'cop', p:'root', n:'Copy', t:'Rewrite the plan blurbs', ic:'edit', av:'m' },
    { id:'cop1', p:'cop', n:'Post to Slack', t:'Waits for your OK', app:'slack' }
  ];
  // the run, the same in both. on(event, node) tells the design what changed: 'state' (its state or its line of text),
  // 'join' (the retry), 'ask' (a fix for the failed step, or the post's OK), 'tick' (ten times a second) and 'end'
  function atrModel(c, on){
    const all = ATR_RUN.map(x => ({ cost:0, s:'queued', ...x, kids:[] })), by = id => all.find(n => n.id === id);
    all.forEach(n => { n.parent = n.p ? by(n.p) : null; n.lv = n.parent ? n.parent.lv + 1 : 0; if (n.parent) n.parent.kids.push(n); });
    const T = all[0];
    // each agent's step of the accent, for its bars (the orchestrator's is the first)
    T.kids.forEach((k, i) => { k.k = i + 1; }); all.forEach(n => { if (!n.k) n.k = n.lv > 1 ? n.parent.k : 1; });
    const sum = n => n.cost + n.kids.reduce((a, k) => a + sum(k), 0);
    const m = { T, all, by, sum, t0:0, ended:0, fix:null, ok:null };
    const set = (n, s, t) => { if (s) n.s = s; if (t !== undefined) n.t = t; on('state', n); };
    // whatever is running spends as it goes, ten times a second, and the clock counts
    c.every(100, () => { if (m.ended) return; m.t0 += .1; all.forEach(n => { if (n.s === 'run' && !n.late) n.cost += n.lv ? .0014 : .0004; }); on('tick'); });
    // a way on waits for you; the person in the demo takes it after a while, unless you have taken over
    const ask = (k, n, ms) => new Promise(res => { m[k] = () => { m[k] = null; res(); }; on('ask', n, k); c.auto(ms, () => m[k] && m[k]()); });
    c.run(async () => {
      await c.wait(700); set(by('res1'), null, 'Reading 3 of 5');
      await c.wait(700); set(by('res1'), null, 'Reading 5 of 5');
      await c.wait(600); set(by('res1'), 'done', '5 pages, 12k words'); set(T, null, '3 agents at work');
      await c.wait(350); set(by('res'), 'done', 'Notes in Pricing v4');
      await c.wait(500); set(by('des1'), 'done', 'Pro and Team done'); set(by('des2'), 'run', 'Matching colours');
      await c.wait(1400); const tk = by('des2'); set(tk, 'fail', 'Missing accent.600');
      await ask('fix', tk, 3200);
      tk.dim = true; const rt = by('des3'); rt.late = false; rt.s = 'run'; on('join', rt); set(tk);
      await c.wait(1500); set(rt, 'done', 'Used accent.500');
      await c.wait(300); set(by('des'), 'done', 'Cards and tokens done'); set(by('cop'), 'run', 'Writing 3 blurbs');
      await c.wait(1500); set(by('cop'), null, '3 blurbs written'); const ps = by('cop1'); set(ps, 'wait', 'Needs your OK');
      await ask('ok', ps, 3200);
      set(ps, 'done', 'Posted to #pricing');
      await c.wait(350); set(by('cop'), 'done', '3 blurbs posted');
      await c.wait(300); set(T, 'done', 'Run finished'); m.ended = m.t0; on('end');
    });
    return m;
  }
  const atrMoney = v => '$' + v.toFixed(2);
  const atrClock = s => Math.floor(s / 60) + ':' + String(Math.floor(s % 60)).padStart(2, '0');
  // who: an agent's avatar in its colour, the orchestrator's in ink, or the app a step works in (as in Classic)
  const atrWho = n => n.app ? `<span class="atr-av app" aria-hidden="true">${BRAND[n.app]}</span>` : `<span class="atr-av${n.av || !n.lv ? '' : ' app'}" aria-hidden="true"${n.av ? ` style="--dm-a:var(--dm-av-${n.av});--dm-ai:var(--dm-av-${n.av}-ink)"` : ''}>${I(n.ic, 'xs')}</span>`;
  // a node's mark: the source disc for the orchestrator while it runs, else its state
  const atrM = n => n.lv ? n.s : n.s === 'run' ? 'src' : n.s;
  const atrG = m => `<span class="atr-g" data-m="${m}" aria-hidden="true">${atrMark(m)}</span>`;
  const atrWord = { queued:'queued', run:'running', wait:'needs you', done:'done', fail:'failed' };
  // the run's header, as in Classic: its title, a dot and a word for how it is doing, the clock and the total
  const ATR_HEAD = t => `<div class="atr-h"><div class="atr-hd">${t}<span class="atr-s"><span class="atr-dot" aria-hidden="true"></span><span class="atr-m">Starting</span><span aria-hidden="true">·</span><span class="atr-time num">0:00</span></span></div><span class="atr-tot num">$0.00</span></div>`;
  function atrHead(r, M){
    const meta = $('.atr-m', r), time = $('.atr-time', r), root = $('.atr', r);
    return () => {
      const live = M.all.filter(n => !n.late), run = live.filter(n => n.lv && n.s === 'run').length, wait = live.some(n => n.s === 'wait');
      const fail = live.filter(n => n.s === 'fail' && !n.dim).length;
      const st = M.ended ? 'Done' : wait ? 'Needs you' : fail && !run ? `${fail} failed` : run ? `${run} running` : 'Starting';
      if (meta.textContent !== st) meta.textContent = st;
      root.dataset.s = M.ended ? 'done' : wait ? 'wait' : fail && !run ? 'fail' : 'run';
      $('.atr-tot', r).textContent = atrMoney(M.sum(M.T)); time.textContent = atrClock(M.ended || M.t0);
    };
  }

  // Cost tree: Classic's tree, its lines and its band, with each row's share of the whole run as a bar after its cost, and
  // the run's cost by agent as one bar under the header
  const ATR_COST = `<div class="atr atr-ct panel" data-s="run">
    ${ATR_HEAD('<b class="atr-t">Redesign the pricing page</b>')}
    <div class="atr-ct-mix" aria-hidden="true"></div>
    <div class="atr-tree" role="tree" aria-label="Agents"><svg class="atr-ln" aria-hidden="true"></svg></div>
    <p class="atr-sr" role="status"></p>
  </div>`;
  function atrCost(r, c){
    const tree = $('.atr-tree', r), mix = $('.atr-ct-mix', r), box = $('.atr', r), sr = $('.atr-sr', r);
    let M, L, head;
    const here = n => !n.late, under = n => n.kids.filter(here);
    function build(n){
      n.el = html(`<div class="atr-n" role="treeitem" aria-level="${n.lv + 1}" aria-selected="false" tabindex="${n.lv ? -1 : 0}" data-id="${n.id}" data-s="${n.s}" style="--dm-lv:${n.lv};--dm-k:var(--dm-k${n.k})"><div class="atr-b"><div class="atr-r">${atrG(atrM(n))}${atrWho(n)}<span class="atr-tx"><span class="atr-nm"></span>${n.kids.length ? `<span class="atr-tg" aria-hidden="true">${I('chev-d', 'xs')}</span>` : ''}<span class="atr-sub"></span></span><span class="atr-q num"><span class="atr-c"></span><i class="atr-ct-bar" aria-hidden="true"><span></span></i></span></div></div></div>`);
      $('.atr-nm', n.el).textContent = n.n; $('.atr-sub', n.el).textContent = n.t;
      if (n.kids.length){ n.el.setAttribute('aria-expanded', 'true'); n.fold = html('<div class="fold atr-kids"><div role="group"></div></div>'); n.kids.forEach(k => n.fold.firstElementChild.appendChild(build(k))); n.el.appendChild(n.fold); }
      if (n.late) n.el.hidden = true;
      return n.el;
    }
    function paint(){
      const total = M.sum(M.T);
      for (const n of M.all){
        if (!here(n)) continue;
        const v = under(n).length ? M.sum(n) : n.cost, ce = $(':scope>.atr-b .atr-c', n.el), t = n.s === 'queued' && !v ? '' : atrMoney(v);
        if (ce.textContent !== t) ce.textContent = t;
        $(':scope>.atr-b .atr-ct-bar', n.el).style.setProperty('--dm-sh', total ? (v / total).toFixed(3) : 0);
        if (under(n).length) ce.dataset.tip = `Its own ${atrMoney(n.cost)}, the rest ${atrMoney(M.sum(n) - n.cost)}`;
        const label = `${n.n}, ${atrWord[n.s]}, ${n.t}${v ? ', ' + atrMoney(v) : ''}`;
        if (n.el.getAttribute('aria-label') !== label) n.el.setAttribute('aria-label', label);
      }
      let at = 0; M.T.kids.forEach((k, i) => { const w = total ? M.sum(k) / total * 100 : 0; mix.children[i].style.setProperty('--dm-x0', at.toFixed(2)); mix.children[i].style.setProperty('--dm-x1', (at + w).toFixed(2)); at += w; });
      head();
    }
    // the way on, in place under a row: the fix for the failed step, or Approve and Hold for the post
    function ask(n, how){
      const old = $(':scope>.atr-b>.atr-ask:not(.atr-gone)', n.el); if (old) atrDrop(old);
      if (!how) return null;
      const b = html(`<div class="atr-ask">${how.map(([k, label]) => `<button type="button" class="pill sm ${k === 'yes' || k === 'fix' ? 'primary' : 'line'} atr-${k}">${label}</button>`).join('')}</div>`);
      $(':scope>.atr-b', n.el).appendChild(b); return b;
    }
    M = atrModel(c, (ev, n, k) => {
      if (ev === 'state'){
        n.el.dataset.s = n.s; const g = $(':scope>.atr-b .atr-g', n.el), m = atrM(n);
        if (g.dataset.m !== m){ g.dataset.m = m; g.innerHTML = atrMark(m); }
        $(':scope>.atr-b .atr-sub', n.el).textContent = n.t;
        if (n.dim) n.el.setAttribute('data-dim', '');
        if (n.s !== 'wait' && n.s !== 'fail') ask(n, null);
        if (n.dim) ask(n, null);
        if (n.s === 'fail') sr.textContent = `${n.n} failed: ${n.t}`;
      }
      if (ev === 'join'){ n.el.dataset.s = n.s; const g = $(':scope>.atr-b .atr-g', n.el); g.dataset.m = n.s; g.innerHTML = atrMark(n.s); n.el.hidden = false; }
      if (ev === 'ask'){
        if (k === 'fix') $('.atr-fix', ask(n, [['fix', 'Use accent.500']])).onclick = () => M.fix && M.fix();
        else { const b = ask(n, [['yes', 'Approve'], ['no', 'Hold']]); sr.textContent = `${n.n} needs you`;
          $('.atr-yes', b).onclick = () => M.ok && M.ok();
          $('.atr-no', b).onclick = e => { n.t = 'On hold'; $(':scope>.atr-b .atr-sub', n.el).textContent = n.t; e.currentTarget.remove(); $('.atr-yes', b).focus({ preventScroll:true }); }; }
      }
      // done: one line under the tree with the done mark
      if (ev === 'end'){ sr.textContent = 'Run finished'; const sm = html(`<p class="atr-ct-sum"${REDUCE ? '' : ' data-in'}>${atrG('done')}<span>Done in <b class="num">${atrClock(M.ended)}</b> · 3 agents · <b class="num">${atrMoney(M.sum(M.T))}</b></span></p>`); box.insertBefore(sm, sr); }
      if (L && ev !== 'tick') L.frame(performance.now());
      if (head) paint();
    });
    mix.innerHTML = M.T.kids.map(k => `<i style="--dm-k:var(--dm-k${k.k})"></i>`).join('');
    tree.appendChild(build(M.T));
    head = atrHead(r, M); paint();
    L = atrLines(tree); c.loop(t => { L.frame(t); });
    // the keyboard and the pointer, as in Classic: one row in the tab order, the arrows move through the rows you can see,
    // Right and Left open and close a branch, and the chevron folds one
    const open = n => n.el.getAttribute('aria-expanded') !== 'false';
    const visible = () => M.all.filter(n => { if (!here(n)) return false; for (let p = n.parent; p; p = p.parent) if (!open(p)) return false; return true; });
    const pick = n => { M.all.forEach(x => { x.el.tabIndex = x === n ? 0 : -1; x.el.setAttribute('aria-selected', String(x === n)); }); n.el.focus({ preventScroll:true }); };
    const fold = (n, o) => { if (!under(n).length) return; n.el.setAttribute('aria-expanded', String(o)); n.fold.classList.toggle('shut', !o); n.fold.inert = !o; if (!o && n.fold.contains(document.activeElement)) pick(n); };
    c.on(tree, 'click', e => { const row = e.target.closest('.atr-n'); if (!row || e.target.closest('button')) return; const n = M.all.find(x => x.el === row); if (e.target.closest('.atr-tg')) fold(n, !open(n)); else pick(n); });
    c.on(tree, 'keydown', e => {
      if (e.target.closest('button')) return;
      const v = visible(), i = v.findIndex(n => n.el === e.target); if (i < 0) return;
      const n = v[i], k = under(n).length; let go = null;
      if (e.key === 'ArrowDown') go = v[i + 1]; else if (e.key === 'ArrowUp') go = v[i - 1];
      else if (e.key === 'ArrowRight'){ if (k && !open(n)) fold(n, true); else if (k) go = under(n)[0]; }
      else if (e.key === 'ArrowLeft'){ if (k && open(n)) fold(n, false); else go = n.parent; }
      else if (e.key === 'Home') go = v[0]; else if (e.key === 'End') go = v[v.length - 1];
      else if (e.key === 'Enter' || e.key === ' '){ const b = $(':scope>.atr-b>.atr-ask button', n.el); if (b) b.focus(); else pick(n); }
      else return;
      e.preventDefault(); if (go) pick(go);
    });
    // the person in the demo: reads how the design branch's cost splits, takes the fix, then approves the post
    c.story(async s => {
      await s.beat(3); await s.point($(':scope>.atr-b .atr-c', M.by('des').el)); await s.beat(3); s.away();
      await s.until(() => $('.atr-fix', r)); await s.beat(3); await s.tap($('.atr-fix', r)); s.away();
      await s.until(() => $('.atr-yes', r)); await s.beat(3); await s.tap($('.atr-yes', r)); s.away();
      await s.until(() => M.ended); await s.beat(5);
    });
    // it grows with its rows, as Classic does (owner, 17 Nov): no room kept for its tallest moment
    c.offs.push(grow(box));
  }

  // Cost map: every agent and step as a block as wide as its cost, growing live, tinted by how it is doing and carrying its
  // mark; press a block to zoom into it
  const ATR_MAP = `<div class="atr atr-cm panel" data-s="run">
    ${ATR_HEAD('<nav class="atr-cm-crumb atr-t" aria-label="Where you are"></nav>')}
    <div class="atr-cm-map" role="group" aria-label="Cost by agent and step"></div>
    <ul class="atr-cm-lg" aria-label="What the marks mean"><li>${atrG('done')}Done</li><li>${atrG('run')}Running</li><li>${atrG('fail')}Failed</li><li>${atrG('queued')}Queued</li><li><i class="own" aria-hidden="true"></i>Its own work</li></ul>
    <div class="atr-cm-say" aria-live="polite"></div>
    <ul class="atr-cm-key" aria-label="Agents"></ul>
  </div>`;
  function atrMap(r, c){
    const map = $('.atr-cm-map', r), crumb = $('.atr-cm-crumb', r), say = $('.atr-cm-say', r), key = $('.atr-cm-key', r);
    let M, top, W = 0, shown = '', head;
    // each block's place and width, as shares of the branch on show; blocks outside it fade. The branch fills the first row,
    // its children the second and theirs the third, and each branch's own work (what it spends besides its children) closes
    // its row, hatched, so every row adds up
    function lay(){
      const base = top, total = Math.max(1e-6, M.sum(base)), gap = 4, pos = new Map(), own = new Map();
      pos.set(base, { x:0, w:1, lv:0 });
      let x = 0; base.kids.forEach(k => { const w = M.sum(k) / total; pos.set(k, { x, w, lv:1 }); let y = x; k.kids.forEach(g => { const gw = M.sum(k) ? g.cost / M.sum(k) * w : 0; pos.set(g, { x:y, w:gw, lv:2 }); y += gw; }); if (k.kids.length) own.set(k, { x:y, w:M.sum(k) ? k.cost / M.sum(k) * w : 0, lv:2 }); x += w; });
      own.set(base, { x, w:base.cost / total, lv:1 });
      M.all.forEach(n => { if (!n.ob) return; const p = own.get(n); if (!p || p.w * W < 3){ n.ob.classList.add('gone'); return; } n.ob.classList.remove('gone'); n.ob.style.setProperty('--dm-lv', p.lv); n.ob.style.setProperty('--dm-x', (p.x * W).toFixed(1) + 'px'); n.ob.style.setProperty('--dm-w', Math.max(0, p.w * W - gap).toFixed(1) + 'px'); n.ob.dataset.tip = `${n.lv ? n.n : 'The orchestrator'}'s own work, ${atrMoney(n.cost)}`; });
      M.all.forEach(n => {
        const p = pos.get(n), el = n.b; if (!el) return;
        if (!p || p.w * W < 3){ el.classList.add('gone'); el.tabIndex = -1; return; }
        el.classList.remove('gone'); el.tabIndex = 0;
        const px = p.x * W, pw = Math.max(0, p.w * W - (p.lv ? gap : 0));
        el.style.setProperty('--dm-lv', p.lv); el.style.setProperty('--dm-x', px.toFixed(1) + 'px'); el.style.setProperty('--dm-w', pw.toFixed(1) + 'px');
        // a block too narrow for its words keeps its tint and mark, or only its tint, and says them in its tooltip
        const l = $('.atr-cm-l', el), fit = pw > 72 ? 'all' : pw > 28 ? 'mark' : 'none'; if (l.dataset.fit !== fit) l.dataset.fit = fit;
      });
    }
    const ro = new ResizeObserver(() => { W = map.clientWidth; lay(); }); ro.observe(map); c.offs.push(() => ro.disconnect());
    function crumbs(){
      const path = []; for (let p = top; p; p = p.parent) path.unshift(p);
      crumb.innerHTML = path.map((p, i) => i === path.length - 1 ? `<b>${p.lv ? p.n : 'Redesign the pricing page'}</b>` : `<button type="button" data-id="${p.id}">${p.lv ? p.n : 'Pricing page'}</button>${I('chev-r','xs')}`).join('');
      $$('button', crumb).forEach(b => b.onclick = () => go(M.by(b.dataset.id)));
    }
    function go(n){ if (!n || !n.kids.length) return; top = n; crumbs(); lay(); if (document.activeElement && map.contains(document.activeElement)) n.b.focus({ preventScroll:true }); }
    function tell(n){ if (!n){ say.innerHTML = shown; return; } const v = M.sum(n), share = v / Math.max(1e-6, M.sum(M.T)) * 100; say.innerHTML = `<b>${n.n}</b> · ${atrMoney(v)}, ${share.toFixed(0)}% of the run${n.kids.length ? ` · its own ${atrMoney(n.cost)}` : ''}${n.lv ? ' · ' + atrWord[n.s] : ''}`; }
    function blocks(){
      M.all.forEach(n => {
        n.b = html(`<button class="atr-cm-b${n.lv ? '' : ' lv0'}" type="button" data-s="${n.s}" aria-label="${n.n}"><span class="bg"></span><span class="atr-cm-l">${atrG(atrM(n))}<b>${n.lv ? n.n : 'Whole run'}</b><span class="v">–</span></span></button>`);
        n.b.dataset.tip = n.n; map.appendChild(n.b);
        if (n.kids.length){ n.ob = html('<span class="atr-cm-b own" aria-hidden="true"><span class="bg"></span></span>'); map.appendChild(n.ob); }
        n.b.onclick = () => { if (n === top && n.parent) go(n.parent); else if (n.kids.length && n !== top) go(n); else tell(n); };
        ['pointerenter', 'focus'].forEach(ev => n.b.addEventListener(ev, () => tell(n)));
        ['pointerleave', 'blur'].forEach(ev => n.b.addEventListener(ev, () => tell(null)));
      });
    }
    c.on(map, 'keydown', e => { if (e.key === 'Escape' && top.parent){ e.preventDefault(); go(top.parent); } });
    // the agents under the map: each one's mark and avatar, as in the tree, its share and its cost
    function legend(){
      key.innerHTML = M.T.kids.map(k => `<li>${atrG(k.s)}${atrWho(k)}<span class="t">${k.n}</span><span class="p num"></span><span class="c num"></span></li>`).join('');
      M.T.kids.forEach((k, i) => { k.li = key.children[i]; });
    }
    let k10 = 0;
    function paint(full){
      const total = M.sum(M.T);
      M.all.forEach(n => { const v = $('.v', n.b), t = n.s === 'queued' && !M.sum(n) ? 'Queued' : atrMoney(M.sum(n)); if (v.textContent !== t) v.textContent = t; });
      M.T.kids.forEach(k => { const p = Math.round(M.sum(k) / total * 100) + '%', cc = atrMoney(M.sum(k)); if ($('.p', k.li).textContent !== p) $('.p', k.li).textContent = p; if ($('.c', k.li).textContent !== cc) $('.c', k.li).textContent = cc; });
      // the blocks are laid out again twice a second, and glide to their new widths
      if (full || ++k10 % 5 === 0) lay();
      if (head) head();
    }
    const mark = (g, m) => { if (g.dataset.m !== m){ g.dataset.m = m; g.innerHTML = atrMark(m); if (!REDUCE && (m === 'done' || m === 'fail')){ g.removeAttribute('data-drw'); void g.offsetWidth; g.setAttribute('data-drw', ''); } } };
    // the way on for an agent, in its row: Fix for its failed step, Approve for the post
    function way(k, label, tip, run){ const b = html(`<button class="pill sm primary atr-x-fix" type="button">${label}</button>`); b.dataset.tip = tip; $('.c', k.li).after(b); b.onclick = () => { b.remove(); run(); }; }
    M = atrModel(c, (ev, n, k) => {
      if (ev === 'state' || ev === 'join'){ n.b.dataset.s = n.s; mark($('.atr-g', n.b), atrM(n)); if (n.lv === 1) mark($('.atr-g', n.li), n.s); }
      if (ev === 'ask' && k === 'fix'){ way(n.parent, 'Fix', 'Use accent.500', () => M.fix && M.fix()); shown = `<b>${n.n}</b> failed: accent.600 is not in the library`; tell(null); }
      if (ev === 'ask' && k === 'ok'){ way(n.parent, 'Approve', 'Post the blurbs to #pricing', () => M.ok && M.ok()); shown = `<b>${n.n}</b> needs your OK`; tell(null); }
      // a way on the demo took goes, and so does what it said
      if (ev === 'state' && n.lv === 2 && (n.dim || n.s === 'done')){ const b = $('.atr-x-fix', n.parent.li); if (b) b.remove(); shown = ''; tell(null); }
      if (ev === 'end'){ shown = `Done: ${atrMoney(M.sum(M.T))} across 3 agents, most of it on design`; tell(null); }
      paint(ev !== 'tick');
    });
    top = M.T; blocks(); legend(); crumbs(); head = atrHead(r, M); paint(true);
    // the person in the demo: reads the design agent's block, takes the fix, zooms into the design agent and back out, then
    // approves the post
    c.story(async s => {
      await s.beat(4); await s.point(M.by('des').b); tell(M.by('des')); await s.beat(3); s.away(); tell(null);
      await s.until(() => $('.atr-x-fix', key)); await s.beat(3);
      await s.tap($('.atr-x-fix', key)); s.away(); await s.beat(2);
      await s.tap(M.by('des').b); s.away(); await s.beat(4);
      await s.tap($('button', crumb)); s.away();
      await s.until(() => $('.atr-x-fix', key)); await s.beat(3); await s.tap($('.atr-x-fix', key)); s.away();
      await s.until(() => M.ended); await s.beat(4);
    });
  }

  // the switch: the design the card last showed (Classic to begin with) is drawn, and picking another mounts the card again
  // with it, so it plays from the start, entrance and demo; a key that picked it keeps the focus on the switch. Inside another
  // component (as in Agent harness), and in the registry, the code view and the component page (build.js leaves a
  // data-designs="card" switch out of them), it is the classic tree on its own
  const ATR_DS = { cost:[ATR_COST, atrCost], map:[ATR_MAP, atrMap] };
  DM.def('agent-tree', (r, c, card) => {
    let dm = $(':scope>.atr-dm', r);
    if (!dm) return classic(r, c, card);
    if (!c.card || r !== c.st){ dm.replaceWith(...$(':scope>.dm-main', dm).childNodes); return classic(r, c, card); }
    const v = ATR_DS[card._dv] ? card._dv : 'classic';
    if (v === 'classic') classic(r, c, card);
    // (the classic component may have drawn its icons into the stage again, so the switch is found afresh)
    dm = $(':scope>.atr-dm', r);
    const main = $(':scope>.dm-main', dm), sg = $(':scope>.demo .seg2', dm);
    // the card keeps the room the tallest design needs, and the design picked sits in the middle of it, growing with its
    // content from there (CSS: the switch's main part is centred in the room)
    if (v !== 'classic'){ main.innerHTML = ATR_DS[v][0]; ATR_DS[v][1](main, c); }
    $$('button', sg).forEach(b => b.setAttribute('aria-pressed', String(b.dataset.v === v)));
    seg(sg, k => {
      if (k === v) return;
      const kb = sg.contains(document.activeElement) && document.activeElement.matches(":focus-visible");
      card._dv = k; DM.mount(card);
      // it comes back once the new design has started, so it isn't taken for the visitor taking over the new demo
      if (kb) setTimeout(() => { const b = $(`.atr-dm>.demo button[data-v="${k}"]`, card); if (b && (!document.activeElement || document.activeElement === document.body)) b.focus({ preventScroll:true }); }, 120);
    });
  });
}

agent-lanes.css:
/* the card's three designs, picked in the switch under it: Classic (the component above, as it ships), Swimlanes and Crew, each filling the width and
   centred in the room kept for the tallest of them */
.dm.aln-dm{min-height:0}
.aln-dm>.dm-main>*{align-self:stretch}

/* Swimlanes: every agent's work on one clock. Each lane takes its agent's hue (--dm-c its text, --dm-cb its tint, --dm-cm its marks,
   3:1 on the surface): a soft tint for the lane, its steps as bars, and the hook that hands its work down to the next lane.
   A step still to come is a dashed outline; the one at work fills in stripes as the clock reaches it; a finished one is
   solid with its icon; a wait is hatched, with what it waits for. The playhead is grey with the time on it: drag it, click
   a lane or press the arrow keys to look back through the run. Lanes are one height, so the hooks are placed in CSS */
.aln-sw{--dm-lab:168px;--dm-rh:44px;--dm-gap:var(--dm-s-2);--dm-bh:24px;--dm-lt:7%;--dm-aln-sw-pb:#2a7bff;--dm-aln-sw-pm:#1fa66a;--dm-aln-sw-pl:#7a5af5;padding:var(--dm-s-3) var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .aln-sw{--dm-lt:12%;--dm-aln-sw-pb:var(--dm-pb);--dm-aln-sw-pm:var(--dm-pm);--dm-aln-sw-pl:var(--dm-pl)}}
:root[data-theme="dark"] .aln-sw{--dm-lt:12%;--dm-aln-sw-pb:var(--dm-pb);--dm-aln-sw-pm:var(--dm-pm);--dm-aln-sw-pl:var(--dm-pl)}
.aln-sw-h{display:flex;align-items:center;gap:var(--dm-s-4)}
.aln-sw-ht{flex:1;display:flex;flex-direction:column;min-width:0}
.aln-sw-ht b{font-weight:500}
.aln-sw-st{font-size:12.5px;color:var(--dm-muted)}
/* the key: how a step looks to come, at work, done and waiting, in grey since each lane has its own hue */
.aln-sw-key{display:flex;gap:var(--dm-s-3);font-size:11.5px;color:var(--dm-muted)}
.aln-sw-key span{display:inline-flex;align-items:center;gap:var(--dm-s-1)}
.aln-sw-key i{width:16px;height:8px;border-radius:var(--dm-r-xs)}
.aln-sw-key .next{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-fg2) 50%,transparent)}
.aln-sw-key .run{background:repeating-linear-gradient(135deg,color-mix(in srgb,var(--dm-fg2) 40%,var(--dm-surface)) 0 2px,color-mix(in srgb,var(--dm-fg2) 16%,var(--dm-surface)) 2px 4px)}
.aln-sw-key .done{background:var(--dm-fg2)}
.aln-sw-key .wait{background:repeating-linear-gradient(135deg,color-mix(in srgb,var(--dm-fg2) 30%,transparent) 0 1px,transparent 1px 3px)}
.aln-sw-grid{position:relative}
.aln-sw-ax{position:relative;height:24px;margin-left:var(--dm-lab);font-size:11px;color:var(--dm-muted)}
.aln-sw-ticks span{position:absolute;top:1px;transform:translateX(-50%)}
.aln-sw-ticks span:first-child{transform:none}.aln-sw-ticks span:last-child{transform:translateX(-100%)}
.aln-sw-rows{position:relative;display:flex;flex-direction:column;gap:var(--dm-gap)}
.aln-sw-row{display:grid;grid-template-columns:var(--dm-lab) minmax(0,1fr);align-items:center;height:var(--dm-rh)}
.aln-sw-who{display:flex;align-items:center;gap:var(--dm-s-2);min-width:0;padding-right:var(--dm-s-2)}
.aln-sw-av{width:28px;height:28px;border-radius:var(--dm-r-sm);display:grid;place-items:center;flex:none;background:var(--dm-cb);color:var(--dm-c)}
.aln-sw-av .i{width:14px;height:14px;color:inherit}
.aln-sw-row[data-s="work"] .aln-sw-av{animation:alnswbreathe 2s var(--dm-ease-io) infinite}
@keyframes alnswbreathe{50%{opacity:.6}}
/* the agent a hand-off reaches gives a small nod */
.aln-sw-row.got .aln-sw-av{animation:alnswgot .6s var(--dm-ease)}
@keyframes alnswgot{40%{transform:scale(1.15)}}
.aln-sw-wt{display:flex;flex-direction:column;min-width:0;font-size:12.5px;line-height:1.35}
.aln-sw-wt b{font-weight:500}
.aln-sw-wt span{font-size:11.5px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.aln-sw-row[data-s="work"] .aln-sw-wt span{color:var(--dm-fg2)}
/* the lane: its hue's soft tint, and a faint grey line every three seconds */
.aln-sw-lane{position:relative;height:100%;border-radius:var(--dm-r-in);background:linear-gradient(90deg,transparent 1px,color-mix(in srgb,var(--dm-line) 80%,transparent) 1px 2px,transparent 2px) -1px 0/25% 100%,color-mix(in srgb,var(--dm-cm) var(--dm-lt),var(--dm-surface))}
.aln-sw-b,.aln-sw-w{position:absolute;top:calc(50% - var(--dm-bh) / 2);height:var(--dm-bh);border-radius:var(--dm-r-sm);container-type:inline-size;transition:opacity .3s}
.aln-sw-b{border:1px dashed color-mix(in srgb,var(--dm-cm) 65%,transparent)}
.aln-sw-b.run,.aln-sw-b.done{border-color:transparent}
/* the stretch the clock has passed fills in, drawn with a clip so the bar is never laid out again */
.aln-sw-fl{position:absolute;inset:-1px;border-radius:inherit;overflow:hidden;background:color-mix(in srgb,var(--dm-cm) 20%,var(--dm-surface));clip-path:inset(0 calc((1 - var(--dm-f,0)) * 100%) 0 0);transition:clip-path .1s linear}
.aln-sw-fl i{position:absolute;top:0;bottom:0;left:-15px;right:0;display:none;background:repeating-linear-gradient(135deg,color-mix(in srgb,var(--dm-cm) 26%,transparent) 0 5px,transparent 5px 10px)}
.aln-sw-b.run .aln-sw-fl i{display:block;animation:alnswstripe .9s linear infinite}
.aln-sw.paused :is(.aln-sw-b.run .aln-sw-fl i,.aln-sw-av){animation-play-state:paused}
@keyframes alnswstripe{to{transform:translateX(14.14px)}}
.aln-sw-b.done .aln-sw-fl{background:var(--dm-cm)}
.aln-sw-fl .i{position:absolute;left:var(--dm-s-2);top:calc(50% - 6px);color:var(--dm-c)}
.aln-sw-b.done .aln-sw-fl .i{color:var(--dm-surface)}
@container (max-width:19px){.aln-sw-fl .i{display:none}}
/* a wait: hatched in the lane's hue, with what it waits for where there is room */
.aln-sw-w{background:repeating-linear-gradient(135deg,color-mix(in srgb,var(--dm-cm) 16%,transparent) 0 2px,transparent 2px 6px);clip-path:inset(0 calc((1 - var(--dm-f,0)) * 100%) 0 0);transition:clip-path .1s linear,opacity .3s}
