}

attachment-tray.css:
/* the card's three designs, picked in the switch under it: Classic (the component above, as it ships), Composer and Context budget. Each fills the
   width and sits centred in the room kept for the tallest of them. Classic keeps room for its three sample files, so its
   drop zone stays put as they come in */
.dm.atx-dm{min-height:0}
.atx-dm>.dm-main>*{align-self:stretch}
.atx-dm .atx-list{min-height:164.5px}
/* in Clean the card grows with its files instead (owner, 17 Nov: no room kept for a later state) */
:root[data-style="clean"] .atx-dm .atx-list,:root [data-style="clean"] .atx-dm .atx-list,:root [data-style="clean"].atx-dm .atx-list{min-height:0}
/* what both designs share: a clear file input over the control that opens it, and a grey picture of what is in each file
   (a page for a PDF, frames for a Figma file, a grid for a sheet, a scene for an image), its kind in the site's grey tag */
.atx-pick{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer;font-size:0}
.atx-art{display:block;width:100%;height:100%}
.atx-art .pg{fill:var(--dm-surface)}
.atx-art .ln{fill:color-mix(in srgb,var(--dm-fg) 14%,transparent)}
.atx-art .ac{fill:color-mix(in srgb,var(--dm-fg) 26%,transparent)}
.atx-art .ac2{fill:color-mix(in srgb,var(--dm-fg) 9%,transparent)}
.atx-art .ed{fill:none;stroke:color-mix(in srgb,var(--dm-fg) 12%,transparent);stroke-width:1}
.atx-art .gd{stroke:color-mix(in srgb,var(--dm-fg) 12%,transparent);stroke-width:1}
@keyframes atxpopin{from{opacity:0;transform:translateY(10px) scale(.92)}}
.atx-popin{animation:atxpopin .5s var(--dm-ease) backwards}
:root:not([data-style="soft"],[data-style="clean"]) .atx-popin:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){animation:bpin .3s var(--dm-ease) backwards}

/* Composer: files ride in the message box as previews that fill from the foot as they upload. Empty, the tray shows a line
   drawing of files dropping into a tray, in the site's greys with the accent on the top sheet. Dropped files land in place
   one after another and settle with a small bounce; the box gives a little as they hit it */
.atx-cmp{display:flex;flex-direction:column}
.atx-cmp-box{position:relative;display:flex;flex-direction:column;gap:var(--dm-s-1);padding:var(--dm-s-2);border-radius:var(--dm-r-box);background:var(--dm-surface);box-shadow:var(--dm-shadow);transition:box-shadow .3s}
@supports (corner-shape:squircle){.atx-cmp-box{corner-shape:squircle;border-radius:var(--dm-r-box-sq)}}
.atx-cmp-box.thud{animation:atxcmpthud .42s var(--dm-ease) .44s}
@keyframes atxcmpthud{35%{transform:translateY(1.5px) scale(.996)}}
.atx-cmp-tray{position:relative;min-height:126.5px}
.atx-cmp-list{position:relative;display:flex;gap:var(--dm-s-2);min-height:126.5px;padding:var(--dm-s-2);overflow-x:auto;scrollbar-width:none}
.atx-cmp-list::-webkit-scrollbar{display:none}
/* the empty tray: the drawing and a short line, inside a dashed drop target at half strength */
.atx-cmp-empty{position:absolute;inset:0 0 4px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:var(--dm-s-2);text-align:center;padding:0 var(--dm-s-4);border-radius:var(--dm-r-in);border:1px dashed color-mix(in srgb,var(--dm-faint) 50%,transparent);pointer-events:none;transition:opacity .26s var(--dm-ease),transform .3s var(--dm-ease)}
.atx-cmp-empty.out{opacity:0;transform:scale(.98)}
.atx-cmp-empty p{display:flex;flex-direction:column;align-items:center;margin:0;font-size:12.5px;line-height:1.45;color:var(--dm-muted)}
.atx-cmp-empty b{font-weight:500;font-size:13px;color:var(--dm-fg)}
.atx-cmp-art{flex:none;width:84px;height:56px;overflow:visible}
.atx-cmp-art *{vector-effect:non-scaling-stroke}
.atx-cmp-art .gd{fill:none;stroke:color-mix(in srgb,var(--dm-faint) 55%,transparent);stroke-width:1;stroke-dasharray:2 3}
.atx-cmp-art .pl{fill:var(--dm-surface)}
.atx-cmp-art .tr-f{fill:var(--dm-wash)}
.atx-cmp-art .sh.b .pl{fill:color-mix(in srgb,var(--dm-accent-mark,var(--dm-accent)) 7%,var(--dm-surface))}
.atx-cmp-art .ln{fill:none;stroke:color-mix(in srgb,var(--dm-line-strong) 55%,var(--dm-surface));stroke-width:1;stroke-linejoin:round;stroke-linecap:round}
.atx-cmp-art .tx{stroke:color-mix(in srgb,var(--dm-field-line-strong) 60%,var(--dm-surface))}
.atx-cmp-art .ac{stroke:color-mix(in srgb,var(--dm-accent-mark) 75%,var(--dm-surface))}
/* the sheets hover over the tray, the top one a little higher, and drop into it as files land */
.atx-cmp-art .sh{animation:atxcmpfloat 3.2s var(--dm-ease-io) infinite;transition:transform .3s var(--dm-ease),opacity .26s}
.atx-cmp-art .sh.b{animation-delay:-1.1s}
@keyframes atxcmpfloat{50%{transform:translateY(-2px)}}
.atx-cmp-empty.out .sh{animation:none;transform:translateY(9px);opacity:0}
.atx-cmp-empty.out .sh.b{transform:translateY(16px)}
/* a file: its picture is veiled until it is up, the veil drawn back from the foot as it goes; a light passes over it while
   the agent reads it */
.atx-cmp-it{position:relative;flex:none;width:84px;display:flex;flex-direction:column;gap:var(--dm-s-1);border-radius:var(--dm-r-in);text-align:left;cursor:grab;touch-action:none;transition:transform .35s var(--dm-ease)}
.atx-cmp-it:focus-visible{outline-offset:2px;border-radius:var(--dm-r-in)}
.atx-cmp-it.drag{cursor:grabbing;z-index:3;transition:none}
.atx-cmp-it.drag .atx-cmp-th{box-shadow:var(--dm-shadow-pop);transform:rotate(-2deg) scale(1.04)}
/* landing: each file comes down from above, a little turned (--dm-r), touches down, lifts a hair and settles */
.atx-cmp-it.land{animation:atxcmpland .64s cubic-bezier(.3,.7,.4,1) calc(160ms + var(--dm-i,0) * 90ms) backwards}
@keyframes atxcmpland{0%{opacity:0;transform:translateY(-28px) rotate(var(--dm-r,0deg)) scale(.92)}45%{opacity:1;transform:translateY(2px) rotate(0deg) scale(1.02,.98)}70%{transform:translateY(-1.5px) scale(1)}100%{transform:none}}
.atx-cmp-th{position:relative;height:72px;border-radius:var(--dm-r-in);overflow:hidden;background:var(--dm-wash);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent);transition:box-shadow .3s,transform .3s var(--dm-ease)}
.atx-cmp-th .atx-art{padding:var(--dm-s-2) var(--dm-s-3) 0}
.atx-cmp-veil{position:absolute;inset:0;background:color-mix(in srgb,var(--dm-surface) 72%,transparent);clip-path:inset(0 0 calc(var(--dm-p,0) * 100%) 0);transition:clip-path .2s linear}
.atx-cmp-it.up .atx-cmp-veil{opacity:0;transition:opacity .4s}
.atx-cmp-scan{position:absolute;left:0;right:0;top:0;height:40%;z-index:1;background:linear-gradient(180deg,transparent,color-mix(in srgb,var(--dm-fg) 7%,transparent),transparent);transform:translateY(-100%);opacity:0;pointer-events:none}
.atx-cmp-it.read .atx-cmp-scan{opacity:1;animation:atxcmpscan 1.2s var(--dm-ease-io) infinite}
@keyframes atxcmpscan{from{transform:translateY(-100%)}to{transform:translateY(250%)}}
.atx-cmp-pc{position:absolute;left:6px;bottom:5px;z-index:2;font-size:11px;font-weight:500;color:var(--dm-fg)}
.atx-cmp-it.up .atx-cmp-pc{display:none}
.atx-cmp-bd{position:absolute;left:6px;top:6px;z-index:2}
/* on the grey picture the kind tag is white, so it is never grey on grey */
.atx-cmp-bd .tag{background:var(--dm-surface)}
.atx-cmp-ok{position:absolute;right:5px;bottom:5px;z-index:2;width:16px;height:16px;border-radius:50%;display:grid;place-items:center;background:var(--dm-ok);color:#fff;transform:scale(0);transition:transform .4s var(--dm-ease)}
.atx-cmp-ok .i{width:10px;height:10px;stroke-width:2.4;color:inherit}
:root[data-theme="dark"] .atx-cmp-ok{color:#0b2414}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .atx-cmp-ok{color:#0b2414}}
.atx-cmp-it.done .atx-cmp-ok{transform:none}
.atx-cmp-x{position:absolute;right:-6px;top:-6px;z-index:4;width:20px;height:20px;border-radius:50%;display:grid;place-items:center;background:var(--dm-raised);color:var(--dm-fg);box-shadow:var(--dm-shadow-pop);opacity:0;transform:scale(.7);transition:opacity .2s,transform .25s var(--dm-ease)}
.atx-cmp-x .i{width:10px;height:10px;stroke-width:2.2;color:inherit}
.atx-cmp-it:focus-within .atx-cmp-x,.atx-cmp-it.peek .atx-cmp-x{opacity:1;transform:none}
@media (hover:hover) and (pointer:fine){.atx-cmp-it:hover .atx-cmp-x{opacity:1;transform:none}}
@media (hover:none){.atx-cmp-x{opacity:1;transform:none}}
.atx-cmp-n{font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--dm-fg)}
.atx-cmp-m{margin-top:-4px;font-size:11px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.atx-cmp-m .shim{font-size:inherit}
.atx-cmp-it.gone{animation:atxcmpgone .3s var(--dm-ease) forwards}
@keyframes atxcmpgone{to{opacity:0;transform:scale(.85)}}
/* the message is a field of its own (the site's field look: a dimmed edge at rest, one step stronger with the focus), so it
   reads as the place to type, in both styles and themes */
.atx-cmp-ta{display:block;width:100%;resize:none;border:0;outline:0;background:var(--dm-surface);padding:10px var(--dm-s-3);border-radius:var(--dm-r-box);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);font:inherit;font-size:13.5px;line-height:1.5;color:var(--dm-fg)}
@supports (corner-shape:squircle){.atx-cmp-ta{corner-shape:squircle;border-radius:var(--dm-r-box-sq)}}
.atx-cmp-ta:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.atx-cmp-ta::placeholder{color:var(--dm-muted)}
/* the field lines up with the files above it (the tray's own inset), and so do + and send below it */
.atx-cmp-ta{width:auto;margin-inline:var(--dm-s-2);max-height:72px;margin-top:var(--dm-s-1);transition:max-height .35s var(--dm-ease),opacity .25s,padding .35s var(--dm-ease),margin .35s var(--dm-ease),box-shadow .2s}
.atx-cmp-box.none .atx-cmp-ta{max-height:0;padding-block:0;margin-top:0;opacity:0;visibility:hidden}
/* + and send sit with the field's edges, with the same room above them (the box's gap and this) as below (this and the box's padding) */
.atx-cmp-f{display:flex;align-items:center;gap:var(--dm-s-2);padding:var(--dm-s-2) var(--dm-s-2) var(--dm-s-1)}
.atx-cmp-add{position:relative;overflow:hidden;cursor:pointer}
.atx-cmp-add:has(.atx-pick:focus-visible){outline:2px solid var(--dm-focus);outline-offset:2px}
.atx-cmp-st{flex:1;font-size:12px;color:var(--dm-muted)}
.atx-cmp-send{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:var(--dm-accent);color:var(--dm-on-accent);transition:background .2s,transform .15s}
.atx-cmp-send .i{color:inherit}
@media (hover:hover) and (pointer:fine){.atx-cmp-send:hover{background:var(--dm-accent-2)}}
.atx-cmp-send:active{transform:scale(.92)}
.atx-cmp-send[disabled]{cursor:not-allowed;background:var(--dm-dis-hatch),var(--dm-dis-fill);color:var(--dm-dis);box-shadow:var(--dm-soft-ring)}
/* a file dragged over the box: the box veils over, says so, and its edge is a quiet grey at half strength */
.atx-cmp-over{position:absolute;inset:0;z-index:5;display:grid;place-items:center;border-radius:inherit;background:color-mix(in srgb,var(--dm-surface) 92%,transparent);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-faint) 50%,transparent);opacity:0;pointer-events:none;transition:opacity .25s}
.atx-cmp-over span{display:inline-flex;align-items:center;gap:var(--dm-s-2);font-size:13px;font-weight:500;color:var(--dm-fg)}
.atx-cmp-over .i{animation:atxbob .9s var(--dm-ease-io) infinite}
.atx-cmp-box.over .atx-cmp-over{opacity:1}
