      await s.tap(cards[0]); s.away(); await s.beat(4);
      await s.tap(cards[2]); s.away(); await s.beat(4);
      await s.tap(cells[11]); s.away(); await s.beat(2);
      await s.tap(cells[11]); s.away(); await s.beat(3);
